import{_ as i,c as o,b as s,o as n}from"./app-CoEY_fQ5.js";const t={};function m(a,e){return n(),o("div",null,e[0]||(e[0]=[s('<p><strong>Commission Types</strong>:-  In <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multivendor Marketplace app for Shopify</a> commission is the admin/merchant share from the seller/vendor&#39;s total earnings.</p><p>Admin can charge any commission(Like Global, seller commission, etc.) in the following 4 ways:-</p><p>Fixed Commission: In this type of commission, only a fixed amount will be deducted from the product base price.</p><p>Percent Commission: In this type of commission, only a percent amount will be deducted from the product base price.</p><p>Fixed + Percent Commission: In this type of commission firstly a fixed amount will be deducted from product base price and then a percent amount will be deducted from the remaining price.</p><p>Percent + Fixed Commission: In this type of commission firstly a percent amount will be deducted from the product base price and then a fixed amount will be deducted from the remaining price.</p><p>Check the below video of Commission setup:</p><p>So let&#39;s understand its workflow:-</p><h3 id="setting-up-global-commission" tabindex="-1"><a class="header-anchor" href="#setting-up-global-commission"><span>SETTING UP GLOBAL COMMISSION</span></a></h3><p>To set up the global commission you need to visit the Commission section in the main menu of the multivendor marketplace app.</p><p>Admin Panel&gt;&gt; Commissions-&gt;&gt; Global commission settings-&gt;&gt; Choose the commission type and enter the commission value-&gt;&gt; Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/a-4.png" alt="Multi Vendor Marketplace Commission "></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/9-6.png" alt="Multi Vendor Marketplace Commission"></p><h3 id="fixed-commission-example" tabindex="-1"><a class="header-anchor" href="#fixed-commission-example"><span>Fixed Commission Example:-</span></a></h3><p>Suppose Fixed commission :USD 100</p><p>Price of seller product :USD 1000</p><p>So  Merchant Share: USD 100 and Vendor Share: (USD 1000-USD 100) = USD 900.</p><h3 id="percent-commission-example" tabindex="-1"><a class="header-anchor" href="#percent-commission-example"><span>Percent Commission Example:-</span></a></h3><p>Suppose Percent commission: 20%</p><p>Price of seller product: USD 1000</p><p>So  Merchant Share: (20%*1000)= USD 200 and Vendor Share: (USD 1000-USD 200) = USD 800.</p><h3 id="fixed-percent-commission-example" tabindex="-1"><a class="header-anchor" href="#fixed-percent-commission-example"><span>Fixed+ Percent Commission Example:-</span></a></h3><p>Fixed commission: USD 100 and Percent commission: USD 20%</p><p>Price of seller product: USD 1000</p><p>Here Firstly &quot;Fixed  commission&quot;  deduct from product base price= (1000-100) = USD 900 and then percent commission from remaining price=(900-20%*900)=USD 720</p><p>So Vendor Share: USD 720 and Merchant Share: USD 280</p><h3 id="percent-fixed-commission-example" tabindex="-1"><a class="header-anchor" href="#percent-fixed-commission-example"><span>Percent+Fixed Commission Example:-</span></a></h3><p>Suppose Percent commission: USD 20% and Fixed commission: USD 100</p><p>Price of seller product: USD 1000</p><p>Here Firstly &quot;Percent commission&quot; will deduct from product base price=(1000-20%*1000)=USD 800 and then fixed commission deduct from remaining price=(800-100) = USD 700</p><p>So Vendor Share: USD 700 and Merchant Share: USD 300</p><h3 id="setting-up-seller-commission" tabindex="-1"><a class="header-anchor" href="#setting-up-seller-commission"><span>Setting Up SELLER COMMISSION</span></a></h3><p>Admin Panel-&gt;&gt;Commissions-&gt;&gt;Seller commission settings-&gt;&gt; Add commission to sellers&gt;&gt; Enter seller email, Choose the commission type and Enter commission value-&gt;&gt; Save</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/b-3.png" alt="Multi Vendor Marketplace Commission"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/c-3.png" alt="Multi Vendor Marketplace Commission"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2018/03/12-4.png" alt="Multi Vendor Marketplace Commission"></p><p>So this way you can set up the seller commission.</p><p>To know more about commissions please also refer the user guide of <a href="https://webkul.com/blog/shopify-multivendor-marketplace-commissions-new-theme/" target="_blank" rel="noopener noreferrer">commissions</a></p><h3 id="commission-types-demo-details" tabindex="-1"><a class="header-anchor" href="#commission-types-demo-details"><span>Commission Types Demo Details</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',40)]))}const l=i(t,[["render",m]]),r=JSON.parse('{"path":"/zenith/Commission/Commission-Type.html","title":"","lang":"en-US","frontmatter":{},"headers":[{"level":3,"title":"SETTING UP GLOBAL COMMISSION","slug":"setting-up-global-commission","link":"#setting-up-global-commission","children":[]},{"level":3,"title":"Fixed Commission Example:-","slug":"fixed-commission-example","link":"#fixed-commission-example","children":[]},{"level":3,"title":"Percent Commission Example:-","slug":"percent-commission-example","link":"#percent-commission-example","children":[]},{"level":3,"title":"Fixed+ Percent Commission Example:-","slug":"fixed-percent-commission-example","link":"#fixed-percent-commission-example","children":[]},{"level":3,"title":"Percent+Fixed Commission Example:-","slug":"percent-fixed-commission-example","link":"#percent-fixed-commission-example","children":[]},{"level":3,"title":"Setting Up SELLER COMMISSION","slug":"setting-up-seller-commission","link":"#setting-up-seller-commission","children":[]},{"level":3,"title":"Commission Types Demo Details","slug":"commission-types-demo-details","link":"#commission-types-demo-details","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"zenith/Commission/Commission-Type.md"}');export{l as comp,r as data};
